// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(bytes32 assertionId) public {
        // Record the policy before calling assertionDisputedCallback
        (bool blockBefore, bool arbitrateBefore, bool discardBefore, bool validateBefore) = 
            (c.getAssertionPolicy(assertionId).blockAssertion,
             c.getAssertionPolicy(assertionId).arbitrateViaEscalationManager,
             c.getAssertionPolicy(assertionId).discardOracle,
             c.getAssertionPolicy(assertionId).validateDisputers);

        // Call assertionDisputedCallback - this is the entry that triggers the bug difference
        c.assertionDisputedCallback(assertionId);

        // Get the policy after the call
        (bool blockAfter, bool arbitrateAfter, bool discardAfter, bool validateAfter) = 
            (c.getAssertionPolicy(assertionId).blockAssertion,
             c.getAssertionPolicy(assertionId).arbitrateViaEscalationManager,
             c.getAssertionPolicy(assertionId).discardOracle,
             c.getAssertionPolicy(assertionId).validateDisputers);

        // The general rule: getAssertionPolicy is immutable - it does not change when assertionDisputedCallback is called
        assertTrue(blockBefore == blockAfter && arbitrateBefore == arbitrateAfter && discardBefore == discardAfter && validateBefore == validateAfter);
    }
}

