pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(bytes32 identifier, uint256 time, bytes memory ancillaryData, bytes32 assertionId) public {
        vm.assume(ancillaryData.length <= 256);

        // Record the price before calling assertionDisputedCallback
        int256 priceBefore = address(c).code.length > 0 ? c.getPrice(identifier, time, ancillaryData) : int256(0);

        // Call assertionDisputedCallback (which should revert if not called by the optimistic asserter)
        // Since we deploy with address(this) as the optimistic asserter, we can call it
        c.assertionDisputedCallback(assertionId);

        // Record the price after
        int256 priceAfter = c.getPrice(identifier, time, ancillaryData);

        // The general rule: the return value of getPrice should not change after assertionDisputedCallback
        assertTrue(priceBefore == priceAfter, "getPrice changed after assertionDisputedCallback");
    }
}

