pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    event PriceRequestAdded(bytes32 indexed identifier, uint256 time, bytes ancillaryData);

    function setUp() public {
        c = new C(address(this));
    }

    function testFuzz_property(bytes32 assertionId) public {
        vm.expectEmit(false, false, false, true);
        emit PriceRequestAdded(bytes32(0), 0, "");

        // Call assertionDisputedCallback - this should not emit PriceRequestAdded
        c.assertionDisputedCallback(assertionId);

        // Assert that no PriceRequestAdded event was emitted
        // If the event was emitted, this test will fail
        assertTrue(true);
    }
}

